pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid excessive gas and ensure we can test both success and failure
        value = bound(value, 0, 100 ether);

        // Record depositsCount before the call
        uint256 depositsBefore = c.depositsCount();

        // Send ETH to make the receive() function called? No, we call sendMoney directly
        // The owner is msg.sender (deployer), so we need to act as owner
        vm.deal(address(this), 100 ether);

        // Try to call sendMoney - it will fail if value > address(this).balance or target reverts
        // We just call it; if it reverts, we catch it
        // We need to ensure we have enough balance for the value we try to send
        if (address(this).balance >= value) {
            // If we have enough funds, the call might succeed or revert based on target
            // We just call and catch revert
            (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
            if (!success) {
                // If call reverted, depositsCount should not change
                uint256 depositsAfter = c.depositsCount();
                assertTrue(depositsAfter == depositsBefore, "depositsCount changed after failed sendMoney");
            } else {
                // If call succeeded, depositsCount may change (through receive(), but sendMoney doesn't trigger receive)
                // Actually sendMoney just makes an external call, it does NOT call receive() on this contract
                // So depositsCount should NOT change even on success
                uint256 depositsAfter = c.depositsCount();
                assertTrue(depositsAfter == depositsBefore, "depositsCount changed after successful sendMoney");
            }
        } else {
            // Not enough balance, the external call will revert due to insufficient funds
            // We can still try and catch
            vm.deal(address(this), value); // give enough balance
            (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
            // Whether success or revert, depositsCount should NOT change
            uint256 depositsAfter = c.depositsCount();
            assertTrue(depositsAfter == depositsBefore, "depositsCount changed after sendMoney");
        }
    }
}

