import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposits, uint256 sendValue) public {
        // Bound initialDeposits to uint256 max - 1 to create overflow edge case
        initialDeposits = bound(initialDeposits, type(uint256).max - 1, type(uint256).max - 1);
        // Set the deposit count directly via vm.store (only way to reach high values)
        // Since depositsCount is public but not settable, we'll use storage manipulation
        vm.store(address(c), bytes32(uint256(1)), bytes32(initialDeposits)); // slot 1 for depositsCount

        // Set sendValue to ensure the receive function is called
        sendValue = bound(sendValue, 1, 1 ether);

        // Send ether to trigger receive() with our high deposit count
        (bool success, ) = address(c).call{value: sendValue}("");

        // The reference contract (with >=) accepts the call when depositsCount == type(uint256).max
        // The mutant (with >) reverts when depositsCount == type(uint256).max
        // So the general rule is: receive() succeeds even when depositsCount is at type(uint256).max
        assertTrue(success, "receive() should succeed when depositsCount is at maximum value");
    }
}

